delete from public.evo_dados where academia_id='d3a00000-0000-4000-8000-00000000de30'; delete from public.evo_eventos where academia_id='d3a00000-0000-4000-8000-00000000de30'; delete from public.placar_docs where academia_id='d3a00000-0000-4000-8000-00000000de30'; delete from public.rodadas where academia_id='d3a00000-0000-4000-8000-00000000de30'; delete from public.fin_contas where academia_id='d3a00000-0000-4000-8000-00000000de30'; delete from public.fin_receitas where academia_id='d3a00000-0000-4000-8000-00000000de30';
select (select count(*) from public.evo_dados where academia_id='d3a00000-0000-4000-8000-00000000de30') dados,(select count(*) from public.placar_docs where academia_id='d3a00000-0000-4000-8000-00000000de30') placar,(select count(*) from public.respostas r join public.rodadas d on d.id=r.rodada_id where d.academia_id='d3a00000-0000-4000-8000-00000000de30') respostas,(select count(*) from public.fin_contas where academia_id='d3a00000-0000-4000-8000-00000000de30') contas;