insert into public.rodadas(id,academia_id,titulo,avaliado,funcao,publico,restrita,config,status,criado_em) values ('demo-rodDiego','d3a00000-0000-4000-8000-00000000de30','Professor de musculação','Diego','musculacao','alunos',false,'{"chamada":"Como você avalia o trabalho de Diego?","blocos":[{"nome":"Atendimento na sala","perguntas":["Diego circula pela sala e se aproxima dos alunos sem esperar ser chamado.","Diego cumprimenta os alunos e sabe o nome da maioria deles.","Diego dá atenção a todos, não só aos alunos mais próximos.","Diego recebe bem os alunos novos e explica como a sala funciona."]},{"nome":"Técnica e segurança","perguntas":["Diego corrige a execução dos exercícios quando vê algo errado.","Diego explica o porquê dos exercícios de um jeito fácil de entender.","Diego se preocupa com a segurança: carga, postura e uso correto dos aparelhos.","Diego demonstra conhecimento técnico atualizado."]},{"nome":"Treinos e resultados","perguntas":["Diego monta e atualiza os treinos dentro do prazo.","O treino montado por Diego combina com o objetivo do aluno.","Diego acompanha a evolução dos alunos e faz as reavaliações."]},{"nome":"Postura e organização","perguntas":["Diego chega no horário e cumpre a escala.","Diego não fica no celular durante o horário de trabalho.","Diego mantém a sala organizada: anilhas, halteres e acessórios no lugar.","Diego trata colegas e alunos com respeito."]},{"nome":"Retenção","perguntas":["Diego percebe quando um aluno está sumindo e avisa a recepção.","Diego motiva os alunos a manter a frequência."]}],"nps":"De 0 a 10, quanto você indicaria Diego como professor para um amigo?","abertas":["O que você mais gosta no atendimento de Diego?","O que Diego poderia fazer melhor na sala?","Mais alguma coisa que a direção precisa saber?"]}'::jsonb,'encerrada','2026-11-03T10:00:00Z');
